#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> array(n);
    for (int i = 0; i < n; i++) {
        cin >> array[i];
    }

    vector<int> parityFlags(n);
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            parityFlags[i] = (array[i] % 2 == 0) ? 1 : -1;
        } else {
            parityFlags[i] = (array[i] % 2 == 0) ? parityFlags[i - 1] + 1 : parityFlags[i - 1] - 1;
        }
    }

    struct DiffEntry {
        int diff;
        int index;
        DiffEntry(int d, int idx) : diff(d), index(idx) {}
    };

    vector<DiffEntry> differences;
    for (int i = 0; i < n - 1; i++) {
        differences.emplace_back(abs(array[i + 1] - array[i]), i);
    }

    std::sort(differences.begin(), differences.end(), [](const DiffEntry &a, const DiffEntry &b) {
        return a.diff < b.diff;
    });

    int count = 0;
    for (const auto &e : differences) {
        if (k >= e.diff && parityFlags[e.index] == 0) {
            k -= e.diff;
            count++;
        }
    }

    cout << count << "\n";

    return 0;
}
